import base64, hashlib, json, os, subprocess, sys, time

SRC = json.loads(r"""{"OiReloadHeapBench.java": "", "OiReloadParityCheck.java": "", "OiReloadHeapBenchExt.java": ""}""")
PKG = "com.binance.chuyennd.research.passspeed"
BASE = "/kaggle/working" if os.path.isdir("/kaggle/working") else os.getcwd()
JD, OUT = os.path.join(BASE, "java"), os.path.join(BASE, "classes")
os.makedirs(JD, exist_ok=True); os.makedirs(OUT, exist_ok=True)
for name, b64 in SRC.items():
    d = base64.b64decode(b64); open(os.path.join(JD, name), "wb").write(d)
    print("[SRC] %s sha256=%s bytes=%d" % (name, hashlib.sha256(d).hexdigest(), len(d)))

def sh(a, env=None, to=2400):
    e = dict(os.environ)
    if env: e.update(env)
    t0 = time.time(); p = subprocess.run(a, capture_output=True, text=True, env=e, timeout=to)
    return p, time.time() - t0

p, _ = sh(["java", "-version"]); print("[TOOL] java:", (p.stderr or p.stdout).strip().splitlines()[0])
p, _ = sh(["javac", "-d", OUT] + [os.path.join(JD, f) for f in SRC])
print("[BUILD] javac rc=%d" % p.returncode)
if p.returncode != 0:
    print(p.stderr[-3000:]); sys.exit(2)

res = {}
def run(cls, tag, args, env, xmx="512m"):
    p, dt = sh(["java", "-Xmx" + xmx, "-cp", OUT, PKG + "." + cls] + args, env)
    print("========== %s @-Xmx%s rc=%d wall=%.1fs ==========" % (tag, xmx, p.returncode, dt))
    print(p.stdout[-4000:])
    if p.stderr.strip(): print("[stderr]", p.stderr[-2500:])
    res[tag] = {"rc": p.returncode, "wall_s": round(dt, 1), "stdout": p.stdout[-4000:], "stderr": p.stderr[-2500:]}

B = "BENCH_BUDGET_MB"
run("OiReloadHeapBench", "bench_legacy", ["legacy", "653", "3", "8640"], {})
run("OiReloadHeapBench", "bench_inplace", ["inplace", "653", "3", "8640"], {B: "200"})
run("OiReloadHeapBenchExt", "ext_legacy", ["legacy", "653", "3", "8640", "64"], {})
run("OiReloadHeapBenchExt", "ext_inplace", ["inplace", "653", "3", "8640", "64"], {B: "200"})
run("OiReloadHeapBenchExt", "ext_inplace_slice", ["inplace_slice", "653", "3", "8640", "64"], {B: "200"})
run("OiReloadHeapBenchExt", "ext_legacy_4g", ["legacy", "653", "3", "8640", "64"], {}, xmx="4g")
run("OiReloadHeapBenchExt", "ext_inplace_4g", ["inplace", "653", "3", "8640", "64"], {B: "200"}, xmx="4g")
run("OiReloadParityCheck", "parity", ["20", "8640"], {})

json.dump(res, open(os.path.join(BASE, "oi_heap_bench_results.json"), "w"), indent=1)
print("[DONE]")
